import{_ as a,o as l,c as i,ag as e}from"./chunks/framework.i8sMDeRW.js";const A=JSON.parse('{"title":"AI PM 成长路线图：从入门到专家（L1-L4）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-career/ai-pm-roadmap.md","filePath":"guide/06-career/ai-pm-roadmap.md","lastUpdated":1778822686000}'),r={name:"guide/06-career/ai-pm-roadmap.md"};function d(o,t,h,n,s,u){return l(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-pm-成长路线图-从入门到专家-l1-l4" tabindex="-1">AI PM 成长路线图：从入门到专家（L1-L4） <a class="header-anchor" href="#ai-pm-成长路线图-从入门到专家-l1-l4" aria-label="Permalink to &quot;AI PM 成长路线图：从入门到专家（L1-L4）&quot;">​</a></h1><blockquote><p><strong>2026-05 更新版</strong>：AI PM 的能力重心已经从“会写 Prompt、会接模型 API”升级为“能设计 Agent 工作流、评估体系、成本模型、安全治理和商业化闭环”。本文提供从 L1 到 L4 的成长路径、项目经验和学习资源。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#l1入门--ai-pm-助理--初级-pm">L1：入门 — AI PM 助理 / 初级 PM</a></li><li><a href="#l2进阶--独立-ai-pm">L2：进阶 — 独立 AI PM</a></li><li><a href="#l3资深--高级-ai-pm--产品-lead">L3：资深 — 高级 AI PM / 产品 Lead</a></li><li><a href="#l4专家--ai-产品总监--首席-pm">L4：专家 — AI 产品总监 / 首席 PM</a></li><li><a href="#成长时间线参考">成长时间线参考</a></li><li><a href="#2026-ai-pm-必备能力变化">2026 AI PM 必备能力变化</a></li><li><a href="#附录学习资源">附录：学习资源</a></li></ul><hr><h2 id="l1-入门-—-ai-pm-助理-初级-pm" tabindex="-1">L1：入门 — AI PM 助理 / 初级 PM <a class="header-anchor" href="#l1-入门-—-ai-pm-助理-初级-pm" aria-label="Permalink to &quot;L1：入门 — AI PM 助理 / 初级 PM&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>理解 AI 产品的基本工作流，能在指导下完成简单需求分析、竞品研究、Prompt 原型、评估样例整理和 PRD 编写。</p><h3 id="核心技能" tabindex="-1">核心技能 <a class="header-anchor" href="#核心技能" aria-label="Permalink to &quot;核心技能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能类别</th><th>具体要求</th></tr></thead><tbody><tr><td>AI 基础</td><td>理解 LLM、Token、上下文窗口、RAG、Embedding、Agent 的基本概念</td></tr><tr><td>Prompt 入门</td><td>能写清晰指令、输出格式、few-shot 示例，知道 Prompt 不是万能方案</td></tr><tr><td>产品基础</td><td>能写 PRD、用户故事、流程图、验收标准</td></tr><tr><td>数据意识</td><td>知道准确率、召回率、任务完成率、满意度、幻觉率等指标</td></tr><tr><td>工具体验</td><td>熟练使用 ChatGPT、Claude、Gemini、Cursor、Copilot 等主流 AI 工具</td></tr></tbody></table><h3 id="项目经验" tabindex="-1">项目经验 <a class="header-anchor" href="#项目经验" aria-label="Permalink to &quot;项目经验&quot;">​</a></h3><ul><li>参与 1-2 个 AI 功能的需求分析和上线流程；</li><li>整理 30-100 条真实评估样例；</li><li>完成一个小型 AI 功能 PRD，例如智能摘要、客服问答、文档解析；</li><li>参与一次 Prompt 优化和人工评估；</li><li>输出一份竞品 AI 功能拆解报告。</li></ul><h3 id="典型产出物" tabindex="-1">典型产出物 <a class="header-anchor" href="#典型产出物" aria-label="Permalink to &quot;典型产出物&quot;">​</a></h3><ul><li>AI 功能 PRD；</li><li>Prompt v1 + 版本记录；</li><li>评估样例表；</li><li>竞品分析；</li><li>上线 FAQ 和用户反馈汇总。</li></ul><hr><h2 id="l2-进阶-—-独立-ai-pm" tabindex="-1">L2：进阶 — 独立 AI PM <a class="header-anchor" href="#l2-进阶-—-独立-ai-pm" aria-label="Permalink to &quot;L2：进阶 — 独立 AI PM&quot;">​</a></h2><h3 id="目标-1" tabindex="-1">目标 <a class="header-anchor" href="#目标-1" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>能独立负责一个 AI 产品模块，完成从场景定义、模型/架构选型、评估体系、灰度上线到数据复盘的闭环。</p><h3 id="核心技能-1" tabindex="-1">核心技能 <a class="header-anchor" href="#核心技能-1" aria-label="Permalink to &quot;核心技能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能类别</th><th>具体要求</th></tr></thead><tbody><tr><td>架构理解</td><td>理解 RAG、Fine-tuning、工具调用、Agent loop、MCP/连接器、沙箱的适用场景</td></tr><tr><td>模型选型</td><td>能按质量、延迟、成本、上下文、工具调用、合规做模型对比</td></tr><tr><td>评估体系</td><td>能设计 golden dataset、人工评分标准、LLM-as-Judge、回归测试</td></tr><tr><td>成本意识</td><td>能估算 token、工具调用、Agent run、缓存和重试成本</td></tr><tr><td>风险意识</td><td>理解 Prompt 注入、幻觉、敏感数据、工具越权和内容安全</td></tr><tr><td>跨团队协作</td><td>能和工程、算法、安全、法务、运营推进上线</td></tr></tbody></table><h3 id="项目经验-1" tabindex="-1">项目经验 <a class="header-anchor" href="#项目经验-1" aria-label="Permalink to &quot;项目经验&quot;">​</a></h3><ul><li>独立主导一个 RAG / Agent / AI SaaS 功能从 0 到 1；</li><li>完成一次模型选型报告，不只比较模型名，而是比较能力层级和单位经济学；</li><li>建立一个包含 100-300 条样例的评估集；</li><li>推动一次灰度发布，观察质量、延迟、成本和反馈；</li><li>定义 AI 功能的用户反馈闭环。</li></ul><h3 id="典型产出物-1" tabindex="-1">典型产出物 <a class="header-anchor" href="#典型产出物-1" aria-label="Permalink to &quot;典型产出物&quot;">​</a></h3><ul><li>模型与架构选型报告；</li><li>评估体系设计；</li><li>成本测算表；</li><li>灰度计划；</li><li>风险与回滚方案。</li></ul><hr><h2 id="l3-资深-—-高级-ai-pm-产品-lead" tabindex="-1">L3：资深 — 高级 AI PM / 产品 Lead <a class="header-anchor" href="#l3-资深-—-高级-ai-pm-产品-lead" aria-label="Permalink to &quot;L3：资深 — 高级 AI PM / 产品 Lead&quot;">​</a></h2><h3 id="目标-2" tabindex="-1">目标 <a class="header-anchor" href="#目标-2" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>能负责一条 AI 产品线或复杂 AI 平台，建立方法论、指标体系和组织协作机制，推动多团队规模化交付。</p><h3 id="核心技能-2" tabindex="-1">核心技能 <a class="header-anchor" href="#核心技能-2" aria-label="Permalink to &quot;核心技能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能类别</th><th>具体要求</th></tr></thead><tbody><tr><td>系统设计</td><td>能设计 RAG、Agent、模型网关、评估平台、可观测性和成本治理</td></tr><tr><td>技术判断</td><td>理解推理优化、缓存、批处理、模型路由、私有部署、数据驻留</td></tr><tr><td>平台思维</td><td>能把单功能经验抽象为平台能力和团队规范</td></tr><tr><td>商业化</td><td>能设计订阅、用量、credits、企业版、安全合规溢价</td></tr><tr><td>治理能力</td><td>能建立 AI 安全、隐私、审计、模型升级和事故响应机制</td></tr><tr><td>组织影响</td><td>能推动 PM、MLE、工程、安全、法务形成统一流程</td></tr></tbody></table><h3 id="项目经验-2" tabindex="-1">项目经验 <a class="header-anchor" href="#项目经验-2" aria-label="Permalink to &quot;项目经验&quot;">​</a></h3><ul><li>负责一个面向真实用户的 AI 产品完整生命周期；</li><li>搭建模型评估或 Agent trace 平台；</li><li>主导一次重大模型升级、供应商切换或架构重构；</li><li>设计 AI 成本和用量治理体系；</li><li>支持企业客户的安全、合规、采购和部署需求。</li></ul><h3 id="典型产出物-2" tabindex="-1">典型产出物 <a class="header-anchor" href="#典型产出物-2" aria-label="Permalink to &quot;典型产出物&quot;">​</a></h3><ul><li>产品线 Roadmap；</li><li>AI 平台能力地图；</li><li>模型升级 playbook；</li><li>企业版商业化方案；</li><li>AI 治理清单和安全评估流程。</li></ul><hr><h2 id="l4-专家-—-ai-产品总监-首席-pm" tabindex="-1">L4：专家 — AI 产品总监 / 首席 PM <a class="header-anchor" href="#l4-专家-—-ai-产品总监-首席-pm" aria-label="Permalink to &quot;L4：专家 — AI 产品总监 / 首席 PM&quot;">​</a></h2><h3 id="目标-3" tabindex="-1">目标 <a class="header-anchor" href="#目标-3" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>能定义公司级 AI 产品战略，判断技术与商业周期，构建组织能力，并对行业方法论产生影响。</p><h3 id="核心技能-3" tabindex="-1">核心技能 <a class="header-anchor" href="#核心技能-3" aria-label="Permalink to &quot;核心技能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能类别</th><th>具体要求</th></tr></thead><tbody><tr><td>战略判断</td><td>能预判 1-3 年 AI 应用、Agent、模型平台、治理和商业化趋势</td></tr><tr><td>投资决策</td><td>能评估自研、采购、开源、私有部署、合作生态的 ROI</td></tr><tr><td>组织建设</td><td>能搭建 AI PM、评估、AI 平台、数据治理和安全治理机制</td></tr><tr><td>商业模式</td><td>能设计从个人订阅到企业合约、用量承诺、专属容量的商业体系</td></tr><tr><td>外部影响</td><td>能通过文章、演讲、开源、标准参与建立行业影响力</td></tr><tr><td>责任治理</td><td>能建立 AI 伦理、合规、风险和事故响应的管理框架</td></tr></tbody></table><h3 id="项目经验-3" tabindex="-1">项目经验 <a class="header-anchor" href="#项目经验-3" aria-label="Permalink to &quot;项目经验&quot;">​</a></h3><ul><li>主导公司级 AI 产品战略；</li><li>打造百万级用户或千万级营收的 AI 产品；</li><li>建立跨组织 AI 平台或中台；</li><li>参与行业标准、政策、生态合作或开源项目；</li><li>带领团队完成多条 AI 产品线商业化。</li></ul><hr><h2 id="成长时间线参考" tabindex="-1">成长时间线参考 <a class="header-anchor" href="#成长时间线参考" aria-label="Permalink to &quot;成长时间线参考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>典型年限</th><th>关键里程碑</th></tr></thead><tbody><tr><td>L1 → L2</td><td>1-2 年</td><td>独立完成第一个 AI 功能上线</td></tr><tr><td>L2 → L3</td><td>2-3 年</td><td>主导一个完整 AI 产品 / 模块从 0 到 1</td></tr><tr><td>L3 → L4</td><td>3-5 年</td><td>负责 AI 产品线、平台或团队</td></tr><tr><td>L4+</td><td>5 年以上</td><td>形成公司级战略和行业影响力</td></tr></tbody></table><blockquote><p>注意：AI 行业变化快，成长速度取决于项目密度、技术理解和跨团队影响力，不完全取决于年限。</p></blockquote><hr><h2 id="_2026-ai-pm-必备能力变化" tabindex="-1">2026 AI PM 必备能力变化 <a class="header-anchor" href="#_2026-ai-pm-必备能力变化" aria-label="Permalink to &quot;2026 AI PM 必备能力变化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>过去更重要</th><th>现在更重要</th></tr></thead><tbody><tr><td>会写 Prompt</td><td>会设计评估、数据和反馈闭环</td></tr><tr><td>会接模型 API</td><td>会设计模型路由和成本治理</td></tr><tr><td>会做聊天产品</td><td>会做 Agent 工作流和工具权限</td></tr><tr><td>关注回答质量</td><td>同时关注质量、成本、延迟、安全、合规</td></tr><tr><td>只看模型能力</td><td>关注模型 + harness + workflow + governance</td></tr><tr><td>只做功能上线</td><td>做灰度、回滚、审计和持续运营</td></tr></tbody></table><h3 id="ai-pm-的五个长期护城河" tabindex="-1">AI PM 的五个长期护城河 <a class="header-anchor" href="#ai-pm-的五个长期护城河" aria-label="Permalink to &quot;AI PM 的五个长期护城河&quot;">​</a></h3><ol><li><strong>场景洞察</strong>：知道哪些问题值得用 AI 解决；</li><li><strong>系统思维</strong>：把模型、数据、工具、流程、权限连成系统；</li><li><strong>评估能力</strong>：能用数据判断 AI 是否真的变好；</li><li><strong>商业意识</strong>：能让 AI 功能在成本上可持续；</li><li><strong>治理意识</strong>：能让 AI 产品安全、合规、可控地规模化。</li></ol><hr><h2 id="附录-学习资源" tabindex="-1">附录：学习资源 <a class="header-anchor" href="#附录-学习资源" aria-label="Permalink to &quot;附录：学习资源&quot;">​</a></h2><h3 id="入门" tabindex="-1">入门 <a class="header-anchor" href="#入门" aria-label="Permalink to &quot;入门&quot;">​</a></h3><ul><li>DeepLearning.AI — AI For Everyone；</li><li>OpenAI Cookbook；</li><li>Anthropic Prompt Engineering Guide；</li><li>Google Machine Learning Crash Course；</li><li>Prompt Engineering Guide by DAIR.AI。</li></ul><h3 id="进阶" tabindex="-1">进阶 <a class="header-anchor" href="#进阶" aria-label="Permalink to &quot;进阶&quot;">​</a></h3><ul><li>Designing Machine Learning Systems — Chip Huyen；</li><li>Building LLM Apps / LLM 应用工程相关资料；</li><li>LangChain / LangGraph 文档；</li><li>LlamaIndex 文档；</li><li>RAGAS / DeepEval / LangSmith / Weights &amp; Biases Weave。</li></ul><h3 id="agent-与治理" tabindex="-1">Agent 与治理 <a class="header-anchor" href="#agent-与治理" aria-label="Permalink to &quot;Agent 与治理&quot;">​</a></h3><ul><li>Model Context Protocol 文档；</li><li>OWASP Top 10 for LLM Applications；</li><li>NIST AI Risk Management Framework；</li><li>EU AI Act 官方信息；</li><li>各主流模型供应商的 model card、system card、安全报告和 API 文档。</li></ul><h3 id="持续跟踪" tabindex="-1">持续跟踪 <a class="header-anchor" href="#持续跟踪" aria-label="Permalink to &quot;持续跟踪&quot;">​</a></h3><ul><li>State of AI Report；</li><li>a16z AI；</li><li>Sequoia AI Ascent / AI market analysis；</li><li>The Batch；</li><li>Simon Willison Blog；</li><li>Lilian Weng Blog；</li><li>Import AI Newsletter。</li></ul><hr><blockquote><p><strong>结语</strong>：AI PM 的核心不是“更懂模型”，而是更懂如何把不确定的模型能力转化为确定的用户价值、业务结果和可治理的产品系统。</p></blockquote>',64)])])}const c=a(r,[["render",d]]);export{A as __pageData,c as default};
